CREATE TABLE TP_ADMIN_AUDIT_V1 (
  EVENT_ID char(36) NOT NULL,
  ACTOR_ID varchar(100) NOT NULL,
  TARGET_ID char(36) DEFAULT NULL,
  ACTION varchar(30) NOT NULL,
  RESULT varchar(10) NOT NULL,
  OCCURRED_AT datetime(6) NOT NULL,
  REASON varchar(500) NOT NULL,
  REQUEST_ID varchar(100) NOT NULL,
  ERROR_CODE varchar(100) DEFAULT NULL,
  BEFORE_JSON longtext DEFAULT NULL,
  AFTER_JSON longtext DEFAULT NULL,
  ACTOR_USERNAME varchar(100) DEFAULT NULL,
  TARGET_USERNAME varchar(100) DEFAULT NULL,
  PRIMARY KEY (EVENT_ID),
  KEY IX_TP_ADMIN_AUDIT_TIME (OCCURRED_AT, EVENT_ID),
  CONSTRAINT CHK_TP_ADMIN_AUDIT_RESULT CHECK (RESULT IN ('success','denied')),
  CONSTRAINT CHK_TP_ADMIN_AUDIT_BEFORE CHECK (BEFORE_JSON IS NULL OR JSON_VALID(BEFORE_JSON)),
  CONSTRAINT CHK_TP_ADMIN_AUDIT_AFTER CHECK (AFTER_JSON IS NULL OR JSON_VALID(AFTER_JSON)),
  CONSTRAINT CHK_TP_ADMIN_AUDIT_ACTION CHECK (
    ACTION IN ('create','update','reset-password','list','delete','audit-list','permissions-update')
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci
  COMMENT='territorio-paysandu admin-audit-v1';
